.chaos-card[data-modifier=mega_frogs]{background:linear-gradient(135deg,#425c32,#688447);border-color:#d9f6ab}
.chaos-card[data-modifier=super_suckers]{background:linear-gradient(135deg,#7c3c75,#a75297);border-color:#ffc3f0}
